test("types", () => { expect("s").to.be.a("string"); expect([]).to.be.an("array"); expect(null).to.be.a("null"); expect({}).to.be.an("object"); });
test("type fails", () => expect(5).to.be.a("string"));
test("truthiness", () => { expect(1).to.be.ok; expect(0).to.not.be.ok; expect(true).to.be.true; expect(false).to.be.false; expect(null).to.be.null; expect(undefined).to.be.undefined; expect(0).to.exist; expect(null).to.not.exist; });
test("ok fails", () => expect(0).to.be.ok);
test("numbers", () => { expect(5).to.be.above(4).and.below(6); expect(5).to.be.at.least(5); expect(5).to.be.at.most(5); expect(5).to.be.within(1, 10); expect(5).gt(4); expect(5).lte(5); expect(1.5).to.be.closeTo(1.4, 0.2); });
test("above fails", () => expect(3).to.be.above(5));
test("include", () => { expect("foobar").to.include("oba"); expect([1, 2, 3]).to.include(2); expect({ a: 1, b: 2 }).to.include({ a: 1 }); expect([{ a: 1 }]).to.deep.include({ a: 1 }); expect([1, 2]).to.contain(1); });
test("include fails", () => expect([1, 2, 3]).to.include(4));
test("property", () => { expect({ a: { b: 2 } }).to.have.property("a").that.has.property("b", 2); expect({ a: { b: [5] } }).to.have.nested.property("a.b[0]", 5); expect({ x: 1 }).to.have.own.property("x"); expect({ x: 1 }).to.not.have.property("y"); });
test("property fails", () => expect({ a: 1 }).to.have.property("a", 2));
test("length", () => { expect([1, 2, 3]).to.have.lengthOf(3); expect("abc").to.have.length(3); expect([1, 2, 3]).to.have.length.above(2); });
test("length fails", () => expect([1, 2]).to.have.lengthOf(3));
test("empty", () => { expect([]).to.be.empty; expect("").to.be.empty; expect({}).to.be.empty; expect([1]).to.not.be.empty; });
test("keys and members", () => { expect({ a: 1, b: 2 }).to.have.all.keys("a", "b"); expect({ a: 1, b: 2 }).to.have.any.keys("a", "z"); expect({ a: 1, b: 2 }).to.include.keys("a"); expect([1, 2, 3]).to.have.members([3, 2, 1]); expect([1, 2, 3]).to.include.members([2]); expect([{ a: 1 }]).to.have.deep.members([{ a: 1 }]); });
test("keys fail", () => expect({ a: 1 }).to.have.all.keys("a", "b"));
test("oneOf, match, string", () => { expect(2).to.be.oneOf([1, 2]); expect("abc").to.match(/^a/); expect("abc").to.have.string("bc"); });
test("oneOf fails", () => expect(3).to.be.oneOf([1, 2]));
test("throw, satisfy, instanceOf", () => { expect(() => { throw new TypeError("bad thing"); }).to.throw(TypeError, "bad"); expect(() => 1).to.not.throw(); expect(4).to.satisfy((n) => n % 2 === 0); expect([]).to.be.instanceOf(Array); });
test("throw fails", () => expect(() => 1).to.throw());
test("NaN", () => expect(NaN).to.be.NaN);
